// 處理 GitHub API 回傳
const data = $input.first().json;
const items = data.items || [];

return items.slice(0, 8).map(r => ({
  json: {
    title: r.full_name || r.name,
    summary: r.description || '無描述',
    url: r.html_url,
    source: 'GitHub',
    score: Math.min(Math.floor((r.stargazers_count||0)/50), 10),
    tags: [r.language||'開源', '熱門']
  }
}));

// 處理 HN ID 清單
const data = $input.first().json;
const ids = Array.isArray(data) ? data : Object.values(data);

return ids.slice(0, 10).map(id => ({
  json: {url: `https://hacker-news.firebaseio.com/v0/item/${id}.json`}
}));

// 處理 HN 單篇內容
const item = $input.first().json;
return [{
  json: {
    title: item.title || '無標題',
    summary: item.text ? item.text.substring(0, 150) : (item.title || ''),
    url: item.url || `https://news.ycombinator.com/item?id=${item.id}`,
    source: 'Hacker News',
    score: item.score ? Math.min(Math.floor(item.score / 10), 10) : 5,
    tags: ['科技', '討論']
  }
}];

// 合併所有新聞
const ghNews = $('處理GH資料').all().map(i => i.json);
const hnNews = $('處理HN單篇').all().map(i => i.json).filter(j => j && j.title);
const allNews = [...ghNews, ...hnNews];

// 統計熱搜
const kw = {};
allNews.forEach(n => {
  (n.title + ' ' + n.summary).split(/[\s]+/).forEach(w => {
    if (w.length > 3 && !['https','github','http','www','com','org'].includes(w.toLowerCase())) {
      kw[w] = (kw[w]||0) + 1;
    }
  });
});

const trending = Object.entries(kw).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([w,c])=>({word:w,count:c}));

return [{json: {news: allNews, trending}}];

// 生成 HTML
const {news, trending} = $input.first().json;
const now = new Date();
const dateStr = now.toLocaleDateString('zh-TW', {year:'numeric', month:'long', day:'numeric'});
const dateFile = now.toISOString().split('T')[0];
const top3 = news.slice(0,3);
const summary = `今日熱點：${top3.map(n=>n.title).join('、')}。共${news.length}篇 AI 與科技圈資訊。`;
const th = trending.map(t => '<div class="trending-item"><div class="count">'+t.count+'</div><div class="tag">'+t.word+'</div></div>').join('');

function rn(list) {
  return list.map(n => '<div class="news-item"><span class="score">'+(n.score||5)+'分</span><h3><a href="'+n.url+'" target="_blank">'+n.title+'</a></h3><p class="desc">'+n.summary+'</p><div class="meta"><span>📍'+n.source+'</span></div><div class="tags">'+(n.tags||[]).map(t=>'<span class="tag">'+t+'</span>').join('')+'</div></div>').join('');
}

const css = '*{margin:0;padding:0;box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;background:#0a0a0f;color:#e5e5e5;min-height:100vh;padding:20px}.container{max-width:900px;margin:0 auto}.header{text-align:center;padding:40px 0;border-bottom:1px solid #222;margin-bottom:40px}.header h1{font-size:2.5em;margin-bottom:10px}.header .emoji{font-size:3em}.header .subtitle{color:#888;margin-bottom:20px}.header .date{color:#666;font-size:0.9em}.summary{background:linear-gradient(135deg,#1a1a2e,#16213e);border-radius:16px;padding:30px;margin-bottom:40px;border-left:4px solid #00d4ff}.summary h2{color:#00d4ff;margin-bottom:15px}.summary p{line-height:1.8;color:#ccc}.trending{margin-bottom:40px}.trending h2{color:#ff6b6b;margin-bottom:20px}.trending-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px}.trending-item{background:#1a1a2e;padding:10px 15px;border-radius:8px;text-align:center}.trending-item .count{color:#00d4ff;font-size:1.2em;font-weight:bold}.trending-item .tag{color:#888}.section-title{color:#fff;margin-bottom:20px;padding-bottom:10px;border-bottom:2px solid #333;font-size:1.3em}.news-item{background:#111;border-radius:12px;padding:20px;margin-bottom:20px;border:1px solid #222}.news-item .score{display:inline-block;background:#ff6b6b;color:#fff;padding:3px 10px;border-radius:20px;font-size:0.85em;font-weight:bold}.news-item h3{margin:10px 0;font-size:1.1em}.news-item h3 a{color:inherit;text-decoration:none}.news-item h3 a:hover{color:#00d4ff}.news-item .desc{color:#999;margin:10px 0;line-height:1.6}.news-item .meta{color:#666;font-size:0.85em}.news-item .tags{margin-top:10px}.news-item .tag{display:inline-block;background:#1a1a2e;color:#00d4ff;padding:3px 10px;border-radius:4px;font-size:0.8em;margin-right:5px}.footer{text-align:center;padding:40px 0;color:#666;font-size:0.85em;border-top:1px solid #222;margin-top:60px}.footer a{color:#00d4ff;text-decoration:none}@media(max-width:600px){body{padding:15px}.header h1{font-size:1.8em}}';

const html = '<!DOCTYPE html><html lang="zh-TW"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>AI Daily - '+dateStr+'</title><style>'+css+'</style></head><body><div class="container"><header class="header"><div class="emoji">🤖</div><h1>AI Daily</h1><p class="subtitle">每天早 8 點，5 分鐘看懂 AI 與科技圈</p><p class="date">更新於 '+dateStr+' · 收錄 '+news.length+' 篇</p></header><div class="summary"><h2>📌 今日總結</h2><p>'+summary+'</p></div><div class="trending"><h2>🔥 今日熱搜</h2><div class="trending-grid">'+th+'</div></div><div class="news-section"><h2 class="section-title">頭條 · AI 前線</h2>'+rn(news.slice(0,5))+'</div><div class="news-section" style="margin-top:40px"><h2 class="section-title">🛠️ 工具 · 開發</h2>'+rn(news.slice(5,10))+'</div><footer class="footer"><p>由 AI 自動生成 · <a href="https://github.com/ming-7065/ai-news-daily">GitHub</a></p><p style="margin-top:10px"><a href="archive.html">📁 過刊列表</a></p></footer></div></body></html>';

const archiveCss = '*{margin:0;padding:0;box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;background:#0a0a0f;color:#e5e5e5;min-height:100vh;padding:40px 20px}.container{max-width:900px;margin:0 auto}.header{text-align:center;padding:40px 0;border-bottom:1px solid #222;margin-bottom:40px}.header h1{font-size:2em;margin-bottom:10px}.header .emoji{font-size:2.5em}.news-item{background:#111;border-radius:12px;padding:20px;margin-bottom:20px;border:1px solid #222}.news-item .score{display:inline-block;background:#ff6b6b;color:#fff;padding:3px 10px;border-radius:20px;font-size:0.85em;font-weight:bold}.news-item h3{margin:10px 0;font-size:1.1em}.news-item h3 a{color:inherit;text-decoration:none}.news-item h3 a:hover{color:#00d4ff}.news-item .desc{color:#999;margin:10px 0;line-height:1.6}.news-item .meta{color:#666;font-size:0.85em}.news-item .tags{margin-top:10px}.news-item .tag{display:inline-block;background:#1a1a2e;color:#00d4ff;padding:3px 10px;border-radius:4px;font-size:0.8em;margin-right:5px}.footer{text-align:center;padding:40px 0;color:#666;font-size:0.85em;border-top:1px solid #222;margin-top:60px}.footer a{color:#00d4ff;text-decoration:none}';

const ah = '<!DOCTYPE html><html lang="zh-TW"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>AI Daily - '+dateStr+'</title><style>'+archiveCss+'</style></head><body><div class="container"><header class="header"><div class="emoji">🤖</div><h1>AI Daily</h1><p class="subtitle">'+dateStr+' 完整新聞</p><p class="date">共 '+news.length+' 篇</p></header><div class="news-section">'+rn(news)+'</div><footer class="footer"><p><a href="index.html">← 返回首頁</a> · <a href="https://github.com/ming-7065/ai-news-daily">GitHub</a></p></footer></div></body></html>';

return [{json: {indexHtml: html, archiveHtml: ah, dateFile, dateStr}}];
